package com.atlasiq.pr;
public final class PrReportRenderer {private PrReportRenderer(){}public static String markdown(PrIntelligenceReport r){StringBuilder b=new StringBuilder("## AtlasIQ Architecture Check\n\n**").append(r.diff().changeCount()).append(" architecture changes detected** · risk **").append(r.impact().riskLevel()).append("** (").append(r.impact().riskScore()).append("/100)\n\n");for(var x:r.breakingChanges())b.append("WARNING **").append(x.kind().toUpperCase()).append(" breaking change** — ").append(x.description()).append("\n\n");for(var x:r.dependencyDelta())b.append("WARNING **Dependency delta** — ").append(x.description()).append("\n\n");if(!r.securityDelta().isEmpty())b.append("### Security delta\n").append(r.securityDelta().size()).append(" new security findings\n\n");int affected=r.blastRadius().stream().mapToInt(PrIntelligenceReport.Blast::affectedComponents).sum();b.append("### Blast radius\n").append(affected).append(" affected component references\n\n");if(!r.policyViolations().isEmpty())b.append("### Architecture policy violations\n").append(r.policyViolations().size()).append(" violation(s) detected\n\n");b.append("### Evidence\nBaseline `").append(r.baselineAnalysisId()).append("` -> candidate `").append(r.candidateAnalysisId()).append("`\n");return b.toString();}}
